/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'fs'

// Read argument
const mode = process.argv[2]
if (!mode || !['json', 'keys'].includes(mode)) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  // Handle stdin read errors
}

// Split lines and remove trailing empty line from final newline
let lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

// Parse
try {
  const doc = parse(lines)

  if (mode === 'json') {
    const json = toJSON(doc)
    process.stdout.write(json)
    process.exit(0)
  } else { // keys
    const keys = toKeys(doc)
    process.stdout.write(keys)
    process.exit(0)
  }
} catch (err) {
  process.stderr.write(err.message + '\n')
  process.exit(2)
}

// Parser
function parse(lines) {
  const root = {}
  let currentTable = root
  let currentPath = []
  const definedTables = new Set()
  const definedKeys = new Map() // maps path to true if defined as a regular key

  definedTables.add('') // root is always defined

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum]
    const trimmed = stripComment(line)

    if (trimmed === '') continue // blank or comment line

    if (trimmed[0] === '[') {
      // Header line
      if (trimmed[0] === '[' && trimmed[1] === '[') {
        // Array of tables header: [[name]]
        const match = trimmed.match(/^\[\[([^\]]+)\]\](.*)$/)
        if (!match) {
          throw new Error(`error: line ${lineNum + 1}: unterminated table header`)
        }
        const nameStr = match[1]
        const after = match[2]

        if (after.trim() !== '') {
          throw new Error(`error: line ${lineNum + 1}: trailing text after a table header`)
        }

        const names = parseNames(nameStr)
        const path = names.join('.')

        // Navigate/create intermediate tables
        currentTable = root
        currentPath = []

        for (let i = 0; i < names.length - 1; i++) {
          const name = names[i]
          if (!(name in currentTable)) {
            currentTable[name] = {}
          }
          const val = currentTable[name]
          if (!isTable(val) && !isArrayOfTables(val)) {
            throw new Error(`error: line ${lineNum + 1}: ${buildPath([...currentPath, name])} is not a table`)
          }
          if (isArrayOfTables(val)) {
            currentTable = val[val.length - 1]
            currentPath.push(name)
          } else {
            currentTable = val
            currentPath.push(name)
          }
        }

        const lastName = names[names.length - 1]
        if (!(lastName in currentTable)) {
          currentTable[lastName] = []
        }
        const val = currentTable[lastName]
        if (!isArrayOfTables(val)) {
          throw new Error(`error: line ${lineNum + 1}: ${buildPath([...currentPath, lastName])} is not an array of tables`)
        }

        // Append new table to array
        const newTable = {}
        val.push(newTable)
        currentTable = newTable
        currentPath.push(lastName)
      } else {
        // Regular table header: [name]
        const match = trimmed.match(/^\[([^\]]+)\](.*)$/)
        if (!match) {
          throw new Error(`error: line ${lineNum + 1}: unterminated table header`)
        }
        const nameStr = match[1]
        const after = match[2]

        if (after.trim() !== '') {
          throw new Error(`error: line ${lineNum + 1}: trailing text after a table header`)
        }

        const names = parseNames(nameStr)
        const path = names.join('.')

        // Check if already defined as explicit table header
        if (definedTables.has(path) && !isIntermediatePath(path, definedTables)) {
          throw new Error(`error: line ${lineNum + 1}: table ${path} is defined twice`)
        }

        // Navigate/create intermediate tables
        currentTable = root
        currentPath = []

        for (let i = 0; i < names.length; i++) {
          const name = names[i]
          const currentPathStr = [...currentPath, name].join('.')

          if (!(name in currentTable)) {
            currentTable[name] = {}
            if (i === names.length - 1) {
              definedTables.add(currentPathStr)
            }
          } else {
            const val = currentTable[name]
            if (!isTable(val) && !isArrayOfTables(val)) {
              throw new Error(`error: line ${lineNum + 1}: ${currentPathStr} is not a table`)
            }
            if (isArrayOfTables(val)) {
              currentTable = val[val.length - 1]
              currentPath.push(name)
              continue
            }
            if (i === names.length - 1) {
              definedTables.add(currentPathStr)
            }
          }

          currentTable = currentTable[name]
          currentPath.push(name)
        }
      }
    } else {
      // Key = value assignment
      const eqIndex = trimmed.indexOf('=')
      if (eqIndex === -1) {
        throw new Error(`error: line ${lineNum + 1}: expected key = value`)
      }

      const keyStr = trimmed.substring(0, eqIndex)
      const valueStr = trimmed.substring(eqIndex + 1)

      const names = parseNames(keyStr)
      if (names.length === 0) {
        throw new Error(`error: line ${lineNum + 1}: expected a name`)
      }

      // Parse value
      const [value, remaining] = parseValue(valueStr)

      if (remaining.trim() !== '') {
        throw new Error(`error: line ${lineNum + 1}: trailing text after a value`)
      }

      // Assign to current table
      let table = currentTable
      let path = [...currentPath]

      for (let i = 0; i < names.length - 1; i++) {
        const name = names[i]
        const currentPathStr = buildPath([...path, name])

        if (!(name in table)) {
          table[name] = {}
        } else {
          const val = table[name]
          if (!isTable(val)) {
            throw new Error(`error: line ${lineNum + 1}: ${currentPathStr} is not a table`)
          }
        }
        table = table[name]
        path.push(name)
      }

      const lastName = names[names.length - 1]
      const fullPath = buildPath([...path, lastName])

      if (lastName in table) {
        throw new Error(`error: line ${lineNum + 1}: key ${fullPath} is defined twice`)
      }

      table[lastName] = value
    }
  }

  return root
}

function stripComment(line) {
  let inString = false
  let stringChar = null
  let result = ''

  for (let i = 0; i < line.length; i++) {
    const char = line[i]

    if (!inString) {
      if (char === '"' || char === "'") {
        inString = true
        stringChar = char
        result += char
      } else if (char === '#' || char === ';') {
        break
      } else {
        result += char
      }
    } else {
      result += char
      if (char === stringChar && (i === 0 || line[i - 1] !== '\\')) {
        inString = false
      }
    }
  }

  return result.trim()
}

function parseNames(str) {
  const names = []
  let current = ''
  let inQuote = false
  let quoteChar = null
  let i = 0

  while (i < str.length) {
    const char = str[i]

    if (!inQuote) {
      if (char === '"' || char === "'") {
        if (current !== '') {
          throw new Error('expected a name')
        }
        inQuote = true
        quoteChar = char
        let name = ''
        i++
        while (i < str.length && str[i] !== quoteChar) {
          if (str[i] === '\\' && quoteChar === '"') {
            i++
            if (i >= str.length) throw new Error('unterminated string')
            const escape = str[i]
            if (escape === 'n') name += '\n'
            else if (escape === 't') name += '\t'
            else if (escape === 'r') name += '\r'
            else if (escape === '0') name += '\0'
            else if (escape === '"') name += '"'
            else if (escape === '\\') name += '\\'
            else if (escape === 'u') {
              i++
              const hex = str.substring(i, i + 4)
              if (hex.length !== 4) throw new Error('invalid escape \\u')
              const code = parseInt(hex, 16)
              if (isNaN(code)) throw new Error('invalid escape \\u' + hex)
              name += String.fromCharCode(code)
              i += 3
            } else {
              throw new Error(`invalid escape \\${escape}`)
            }
          } else if (str[i] === '\\' && quoteChar === "'") {
            name += str[i]
          } else {
            name += str[i]
          }
          i++
        }
        if (i >= str.length) throw new Error('unterminated string')
        names.push(name)
        inQuote = false
        i++
      } else if (char === '.') {
        if (current !== '') {
          names.push(current)
          current = ''
        }
        i++
      } else if (char === ' ' || char === '\t') {
        if (current !== '') {
          names.push(current)
          current = ''
        }
        i++
      } else if (/[A-Za-z0-9_-]/.test(char)) {
        current += char
        i++
      } else {
        throw new Error('expected a name')
      }
    }
  }

  if (current !== '') {
    names.push(current)
  }

  if (names.length === 0) {
    throw new Error('expected a name')
  }

  return names
}

function parseValue(str) {
  str = str.trim()

  if (str === '') {
    throw new Error('expected a value')
  }

  // Boolean
  if (str.startsWith('true')) {
    return [true, str.substring(4)]
  }
  if (str.startsWith('false')) {
    return [false, str.substring(5)]
  }

  // String
  if (str[0] === '"') {
    let value = ''
    let i = 1
    while (i < str.length && str[i] !== '"') {
      if (str[i] === '\\') {
        i++
        if (i >= str.length) throw new Error('unterminated string')
        const escape = str[i]
        if (escape === 'n') value += '\n'
        else if (escape === 't') value += '\t'
        else if (escape === 'r') value += '\r'
        else if (escape === '0') value += '\0'
        else if (escape === '"') value += '"'
        else if (escape === '\\') value += '\\'
        else if (escape === 'u') {
          i++
          const hex = str.substring(i, i + 4)
          if (hex.length !== 4) throw new Error('invalid escape \\u')
          const code = parseInt(hex, 16)
          if (isNaN(code)) throw new Error('invalid escape \\u' + hex)
          value += String.fromCharCode(code)
          i += 3
        } else {
          throw new Error(`invalid escape \\${escape}`)
        }
      } else {
        value += str[i]
      }
      i++
    }
    if (i >= str.length) throw new Error('unterminated string')
    return [value, str.substring(i + 1)]
  }

  if (str[0] === "'") {
    let value = ''
    let i = 1
    while (i < str.length && str[i] !== "'") {
      value += str[i]
      i++
    }
    if (i >= str.length) throw new Error('unterminated string')
    return [value, str.substring(i + 1)]
  }

  // Array
  if (str[0] === '[') {
    const [arr, remaining] = parseArray(str)
    return [arr, remaining]
  }

  // Inline table
  if (str[0] === '{') {
    const [table, remaining] = parseInlineTable(str)
    return [table, remaining]
  }

  // Number or invalid
  let i = 0
  let hasDecimal = false
  let hasExponent = false

  // Optional sign
  if (str[0] === '+' || str[0] === '-') i++

  // Check for valid number format
  let foundDigit = false
  while (i < str.length) {
    const char = str[i]

    if (/[0-9]/.test(char)) {
      foundDigit = true
      i++
    } else if (char === '_') {
      i++
      // Next must be digit
      if (i >= str.length || !/[0-9]/.test(str[i])) {
        // Not a valid number, treat as invalid value
        break
      }
    } else if (char === '.' && !hasDecimal && !hasExponent) {
      hasDecimal = true
      i++
      if (i >= str.length || !/[0-9]/.test(str[i])) {
        break
      }
    } else if ((char === 'e' || char === 'E') && !hasExponent && foundDigit) {
      hasExponent = true
      i++
      if (i < str.length && (str[i] === '+' || str[i] === '-')) {
        i++
      }
      if (i >= str.length || !/[0-9]/.test(str[i])) {
        break
      }
    } else {
      break
    }
  }

  if (foundDigit && i > 0) {
    const numStr = str.substring(0, i).replace(/_/g, '')
    const value = hasDecimal || hasExponent ? parseFloat(numStr) : parseInt(numStr, 10)
    return [value, str.substring(i)]
  }

  // Invalid value
  const match = str.match(/^[^\s,\]\}#;]+/)
  if (match) {
    throw new Error(`invalid value ${match[0]}`)
  }

  throw new Error('expected a value')
}

function parseArray(str) {
  if (str[0] !== '[') throw new Error('unterminated array')

  const arr = []
  let i = 1

  while (i < str.length && str[i] !== ']') {
    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) i++

    if (i >= str.length) throw new Error('unterminated array')
    if (str[i] === ']') break

    const remaining = str.substring(i)
    const [value, newRemaining] = parseValue(remaining)
    arr.push(value)

    const consumed = remaining.length - newRemaining.length
    i += consumed

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) i++

    if (i >= str.length) throw new Error('unterminated array')

    if (str[i] === ',') {
      i++
      // Allow trailing comma
      while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) i++
    } else if (str[i] !== ']') {
      throw new Error('unterminated array')
    }
  }

  if (i >= str.length) throw new Error('unterminated array')

  return [arr, str.substring(i + 1)]
}

function parseInlineTable(str) {
  if (str[0] !== '{') throw new Error('unterminated inline table')

  const table = {}
  let i = 1

  while (i < str.length && str[i] !== '}') {
    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) i++

    if (i >= str.length) throw new Error('unterminated inline table')
    if (str[i] === '}') break

    // Parse key
    const keyRemaining = str.substring(i)
    let keyEnd = 0
    let inQuote = false
    let quoteChar = null

    if (keyRemaining[0] === '"' || keyRemaining[0] === "'") {
      quoteChar = keyRemaining[0]
      inQuote = true
      keyEnd = 1
      while (keyEnd < keyRemaining.length && keyRemaining[keyEnd] !== quoteChar) {
        if (keyRemaining[keyEnd] === '\\' && quoteChar === '"') keyEnd++
        keyEnd++
      }
      if (keyEnd >= keyRemaining.length) throw new Error('unterminated string')
      keyEnd++
    } else {
      while (keyEnd < keyRemaining.length && /[A-Za-z0-9_.-]/.test(keyRemaining[keyEnd])) {
        keyEnd++
      }
    }

    if (keyEnd === 0) throw new Error('expected a name')

    const keyStr = keyRemaining.substring(0, keyEnd)
    let keyNames
    try {
      keyNames = parseNames(keyStr)
    } catch {
      throw new Error('expected a name')
    }

    i += keyEnd

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) i++

    if (i >= str.length || str[i] !== '=') {
      throw new Error('expected = in an inline table')
    }

    i++

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) i++

    const valueRemaining = str.substring(i)
    const [value, newValueRemaining] = parseValue(valueRemaining)
    const consumed = valueRemaining.length - newValueRemaining.length
    i += consumed

    // Set value
    let current = table
    for (let j = 0; j < keyNames.length - 1; j++) {
      const name = keyNames[j]
      if (!(name in current)) {
        current[name] = {}
      }
      current = current[name]
    }
    const lastName = keyNames[keyNames.length - 1]
    table[lastName] = value

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) i++

    if (i >= str.length) throw new Error('unterminated inline table')

    if (str[i] === ',') {
      i++
    } else if (str[i] !== '}') {
      throw new Error('unterminated inline table')
    }
  }

  if (i >= str.length) throw new Error('unterminated inline table')

  return [table, str.substring(i + 1)]
}

function isTable(val) {
  return typeof val === 'object' && val !== null && !Array.isArray(val)
}

function isArrayOfTables(val) {
  return Array.isArray(val) && (val.length === 0 || isTable(val[0]))
}

function buildPath(parts) {
  return parts.join('.')
}

function isIntermediatePath(path, definedTables) {
  // Check if this path was only created as an intermediate for a deeper path
  // This is a simplified check - in practice we'd need to track which paths were created implicitly
  return false
}

function toJSON(obj) {
  return JSON.stringify(obj, null, 2) + '\n'
}

function toKeys(obj, prefix = '') {
  let result = ''

  const keys = Object.keys(obj).sort()

  for (const key of keys) {
    const value = obj[key]
    const path = prefix ? `${prefix}.${key}` : key

    if (Array.isArray(value)) {
      if (value.length > 0 && isTable(value[0])) {
        // Array of tables
        result += `${path} array\n`
        for (const item of value) {
          result += toKeys(item, path)
        }
      } else {
        // Regular array
        result += `${path} array\n`
      }
    } else if (isTable(value)) {
      result += `${path} table\n`
      result += toKeys(value, path)
    } else if (typeof value === 'string') {
      result += `${path} string\n`
    } else if (typeof value === 'number') {
      const type = Number.isInteger(value) ? 'integer' : 'float'
      result += `${path} ${type}\n`
    } else if (typeof value === 'boolean') {
      result += `${path} boolean\n`
    }
  }

  return result
}
