function parseArray(str) {
  if (str[0] !== '[') throw new Error('unterminated array')

  const arr = []
  let i = 1

  while (i < str.length && str[i] !== ']') {
    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) i++

    if (i >= str.length) throw new Error('unterminated array')
    if (str[i] === ']') break

    const remaining = str.substring(i)
    const [value, newRemaining] = parseValue(remaining)
    arr.push(value)

    const consumed = remaining.length - newRemaining.length
    i += consumed

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) i++

    if (i >= str.length) throw new Error('unterminated array')

    if (str[i] === ',') {
      i++
      // Allow trailing comma
      while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) i++
