      quoteChar = keyRemaining[0]
      inQuote = true
      keyEnd = 1
      while (keyEnd < keyRemaining.length && keyRemaining[keyEnd] !== quoteChar) {
        if (keyRemaining[keyEnd] === '\\' && quoteChar === '"') keyEnd++
