function toJSON(obj) {
  return JSON.stringify(obj, null, 2) + '\n'
}

function toKeys(obj, prefix = '') {
  let result = ''

  const keys = Object.keys(obj).sort()

  for (const key of keys) {
    const value = obj[key]
    const path = prefix ? `${prefix}.${key}` : key

    if (Array.isArray(value)) {
      if (value.length > 0 && isTable(value[0])) {
        // Array of tables
        result += `${path} array\n`
        for (const item of value) {
          result += toKeys(item, path)
        }
      } else {
        // Regular array
        result += `${path} array\n`
      }
    } else if (isTable(value)) {
      result += `${path} table\n`
      result += toKeys(value, path)
    } else if (typeof value === 'string') {
      result += `${path} string\n`
    } else if (typeof value === 'number') {
      const type = Number.isInteger(value) ? 'integer' : 'float'
      result += `${path} ${type}\n`
    } else if (typeof value === 'boolean') {
      result += `${path} boolean\n`
    }
  }

  return result
}

